"use client";

import React, { useState, useRef, useEffect, useCallback } from "react";
import { createPortal } from "react-dom";
import { motion, AnimatePresence, type Transition } from "motion/react";
import { cn } from "@/lib/utils";
import * as AvatarPrimitive from "@radix-ui/react-avatar";
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from "@/components/custom/blocks/TooltipBlock";
export { AvatarImage, AvatarFallback } from "@/components/custom/ui/avatar";

// ==========================================
// AVATAR STACK & AVATAR GROUP
// A row of overlapping faces — the "people who…" cue under a headline or
// beside a count. Shows up to `max` faces, folds the rest into a "+N" disc,
// and takes an optional trailing action, like a follow button.
//
// Includes both the classic fan-out AvatarStack and the spring-shifted
// interactive AvatarGroup (inspired by animate-ui).
// ==========================================

export interface StackAvatar {
  src: string;
  alt?: string;
  fallback?: string;
  tooltip?: string;
  name?: string;
  designation?: string;
  role?: string;
}

export type AvatarStackSize = "sm" | "md" | "lg" | "xl";

export interface AvatarProps
  extends React.ComponentPropsWithoutRef<typeof AvatarPrimitive.Root> {
  src?: string;
  alt?: string;
  size?: AvatarStackSize;
  /** Colour of the ring around the face — match the surface it sits on. */
  ringClassName?: string;
}

const SIZES: Record<AvatarStackSize, { box: string; overlap: string; text: string }> = {
  sm: { box: "size-7", overlap: "-space-x-2", text: "text-[10px]" },
  md: { box: "size-9", overlap: "-space-x-2.5", text: "text-[11px]" },
  lg: { box: "size-11", overlap: "-space-x-3", text: "text-xs" },
  xl: { box: "size-12", overlap: "-space-x-3", text: "text-xs" },
};

/**
 * One face, the same disc the stack is built from. Powered by Radix Avatar Root so it
 * supports composable child components like AvatarImage & AvatarFallback, or shorthand src/alt.
 */
export const Avatar = React.forwardRef<
  React.ElementRef<typeof AvatarPrimitive.Root>,
  AvatarProps
>(
  (
    {
      src,
      alt = "",
      size = "md",
      ringClassName = "ring-background",
      className,
      children,
      ...props
    },
    ref,
  ) => (
    <AvatarPrimitive.Root
      ref={ref}
      data-slot="avatar"
      className={cn(
        "relative inline-flex shrink-0 items-center justify-center overflow-hidden rounded-full bg-muted ring-2 cursor-pointer transition-shadow",
        SIZES[size]?.box ?? "size-9",
        ringClassName,
        className,
      )}
      {...props}
    >
      {src ? (
        <>
          <AvatarPrimitive.Image
            src={src}
            alt={alt}
            className="aspect-square h-full w-full object-cover"
          />
          <AvatarPrimitive.Fallback className="bg-muted flex h-full w-full items-center justify-center rounded-full text-xs font-medium">
            {alt ? alt.slice(0, 2).toUpperCase() : ""}
          </AvatarPrimitive.Fallback>
        </>
      ) : (
        children
      )}
    </AvatarPrimitive.Root>
  ),
);
Avatar.displayName = "Avatar";

// ==========================================
// AVATAR GROUP (Animate UI Variant)
// Overlapping avatars that smoothly shift upward with spring physics on hover
// and a single gliding tooltip that tracks between avatars without dipping.
// ==========================================

export interface AvatarGroupTooltipProps {
  className?: string;
  children?: React.ReactNode;
  /** Designation or subtitle displayed underneath the name. */
  designation?: React.ReactNode;
  /** Alias for designation. */
  role?: React.ReactNode;
  layout?: boolean | "position" | "size" | "preserve-aspect";
}

/**
 * Marker component placed inside an Avatar to declare its hover tooltip content and designation.
 */
export function AvatarGroupTooltip(_props: AvatarGroupTooltipProps) {
  return null;
}
AvatarGroupTooltip.displayName = "AvatarGroupTooltip";

export interface AvatarGroupTooltipArrowProps extends React.HTMLAttributes<HTMLSpanElement> {
  tipRadius?: number;
}

export function AvatarGroupTooltipArrow({ className, ...props }: AvatarGroupTooltipArrowProps) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "fill-primary size-3 absolute -bottom-1 left-1/2 -translate-x-1/2 rotate-45 bg-primary pointer-events-none data-[side='bottom']:translate-y-[1px] data-[side='right']:translate-x-[1px] data-[side='left']:translate-x-[-1px] data-[side='top']:translate-y-[-1px]",
        className,
      )}
      {...props}
    />
  );
}
AvatarGroupTooltipArrow.displayName = "AvatarGroupTooltipArrow";

export interface AvatarGroupProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "translate"> {
  children?: React.ReactNode;
  invertOverlap?: boolean;
  translate?: string | number;
  transition?: Transition;
  tooltipTransition?: Transition;
}

interface TooltipItemData {
  title: React.ReactNode;
  designation?: React.ReactNode;
}

export const AvatarGroup = React.forwardRef<HTMLDivElement, AvatarGroupProps>(
  (
    {
      children,
      invertOverlap = true,
      translate = "-30%",
      transition = { type: "spring", stiffness: 300, damping: 17 },
      tooltipTransition = { type: "spring", stiffness: 300, damping: 35 },
      className,
      ...props
    },
    ref,
  ) => {
    const [activeIndex, setActiveIndex] = useState<number | null>(null);
    const [coords, setCoords] = useState<{ x: number; y: number } | null>(null);
    const [mounted, setMounted] = useState(false);
    const itemRefs = useRef<(HTMLDivElement | null)[]>([]);

    useEffect(() => {
      setMounted(true);
    }, []);

    const childArray = React.Children.toArray(children);
    const count = childArray.length;
    const tooltips: (TooltipItemData | null)[] = [];

    const updateCoords = useCallback((index: number) => {
      const el = itemRefs.current[index];
      if (el) {
        const rect = el.getBoundingClientRect();
        setCoords({
          x: rect.left + rect.width / 2 + (typeof window !== "undefined" ? window.scrollX : 0),
          y: rect.top + (typeof window !== "undefined" ? window.scrollY : 0),
        });
      }
    }, []);

    const handleMouseEnter = (index: number) => {
      setActiveIndex(index);
      updateCoords(index);
    };

    useEffect(() => {
      if (activeIndex === null) return;
      const onScrollOrResize = () => {
        updateCoords(activeIndex);
      };
      window.addEventListener("scroll", onScrollOrResize, true);
      window.addEventListener("resize", onScrollOrResize);
      return () => {
        window.removeEventListener("scroll", onScrollOrResize, true);
        window.removeEventListener("resize", onScrollOrResize);
      };
    }, [activeIndex, updateCoords]);

    return (
      <>
        <div
          ref={ref}
          data-slot="avatar-group"
          className={cn("relative flex items-center h-12 -space-x-3 my-6", className)}
          onMouseLeave={() => setActiveIndex(null)}
          {...props}
        >
          {childArray.map((child, index) => {
            if (!React.isValidElement(child)) return child;

            let tooltipNode: React.ReactNode = null;
            let designationNode: React.ReactNode = null;
            const childChildren = (child.props as any)?.children;
            let remainingChildren: React.ReactNode = childChildren;

            if (Array.isArray(childChildren)) {
              const nextArr: React.ReactNode[] = [];
              React.Children.forEach(childChildren, (nested) => {
                if (
                  React.isValidElement(nested) &&
                  (nested.type === AvatarGroupTooltip ||
                    (nested.type as any)?.displayName === "AvatarGroupTooltip")
                ) {
                  tooltipNode = (nested.props as any)?.children;
                  designationNode = (nested.props as any)?.designation || (nested.props as any)?.role;
                } else {
                  nextArr.push(nested);
                }
              });
              remainingChildren = nextArr;
            } else if (
              React.isValidElement(childChildren) &&
              (childChildren.type === AvatarGroupTooltip ||
                (childChildren.type as any)?.displayName === "AvatarGroupTooltip")
            ) {
              tooltipNode = (childChildren.props as any)?.children;
              designationNode = (childChildren.props as any)?.designation || (childChildren.props as any)?.role;
              remainingChildren = null;
            }

            tooltips[index] = tooltipNode ? { title: tooltipNode, designation: designationNode } : null;

            const cleanChild = React.cloneElement(child, {
              ...(child.props as any),
              children: remainingChildren,
            });

            const isHovered = activeIndex === index;

            return (
              <div
                key={index}
                ref={(el) => {
                  itemRefs.current[index] = el;
                }}
                data-slot="avatar-container"
                className="relative cursor-pointer select-none outline-none shrink-0"
                style={{
                  zIndex: invertOverlap ? count - index : index + 1,
                }}
                onMouseEnter={() => handleMouseEnter(index)}
                onFocus={() => handleMouseEnter(index)}
                onPointerMove={() => {
                  if (activeIndex === index) {
                    updateCoords(index);
                  }
                }}
              >
                <motion.div
                  animate={{ y: isHovered ? translate : 0 }}
                  transition={transition}
                >
                  {cleanChild}
                </motion.div>
              </div>
            );
          })}
        </div>

        {/* Floating tooltip portaled outside to document.body to prevent flex layout shifts */}
        {mounted &&
          typeof document !== "undefined" &&
          createPortal(
            <AnimatePresence>
              {activeIndex !== null && coords && tooltips[activeIndex] && (
                <motion.div
                  initial={{ opacity: 0, scale: 0.85, x: coords.x, y: coords.y - 4 }}
                  animate={{
                    opacity: 1,
                    scale: 1,
                    x: coords.x,
                    y: coords.y - 14,
                  }}
                  exit={{ opacity: 0, scale: 0.85, x: coords.x, y: coords.y - 4 }}
                  transition={tooltipTransition}
                  style={{
                    position: "absolute",
                    top: 0,
                    left: 0,
                    pointerEvents: "none",
                    zIndex: 9999,
                  }}
                >
                  <div className="-translate-x-1/2 -translate-y-full flex flex-col items-center">
                    <div className="bg-primary text-primary-foreground z-50 w-fit max-w-xs rounded-md px-3.5 py-1.5 text-xs text-balance shadow-md flex items-center justify-center relative">
                      <div className="overflow-hidden whitespace-nowrap py-0.5">
                        <div key={activeIndex} className="flex flex-col items-start text-left">
                          <motion.span
                            initial={{ opacity: 0, y: 6 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{
                              duration: 0.36,
                              ease: [0.16, 1, 0.3, 1],
                              delay: 0.06,
                            }}
                            className="font-semibold text-xs leading-tight tracking-tight text-primary-foreground whitespace-nowrap"
                          >
                            {tooltips[activeIndex]?.title}
                          </motion.span>
                          {tooltips[activeIndex]?.designation && (
                            <motion.span
                              initial={{ opacity: 0, y: 6 }}
                              animate={{ opacity: 1, y: 0 }}
                              transition={{
                                duration: 0.38,
                                ease: [0.16, 1, 0.3, 1],
                                delay: 0.18,
                              }}
                              className="text-[11px] text-primary-foreground/85 leading-tight mt-1 whitespace-nowrap"
                            >
                              {tooltips[activeIndex]?.designation}
                            </motion.span>
                          )}
                        </div>
                      </div>
                      <span
                        className="fill-primary size-2.5 absolute -bottom-1 left-1/2 -translate-x-1/2 rotate-45 bg-primary pointer-events-none"
                      />
                    </div>
                  </div>
                </motion.div>
              )}
            </AnimatePresence>,
            document.body,
          )}
      </>
    );
  },
);
AvatarGroup.displayName = "AvatarGroup";

// ==========================================
// AVATAR STACK
// ==========================================

export interface AvatarStackProps extends Omit<React.HTMLAttributes<HTMLDivElement>, "translate"> {
  avatars: StackAvatar[];
  size?: AvatarStackSize;
  /** Presentation variant: `default` (smooth fan out) or `shift` (spring lift with tooltip). */
  variant?: "default" | "shift";
  /** Invert overlapping order so the first avatar appears on top. */
  invertOverlap?: boolean;
  /** Vertical displacement for the shift variant (e.g. "-30%"). */
  translate?: string | number;
  /** Faces shown before the rest fold into a count. */
  max?: number;
  /** Colour of the gap between faces — match the surface they sit on. */
  ringClassName?: string;
  /** A trailing element that shares the stack's size, e.g. a "+" button. */
  action?: React.ReactNode;
  /** Faces slide apart a little when the stack is hovered. */
  spreadOnHover?: boolean;
  /** A hovered face rises above its neighbours and grows a touch, so it can be seen whole. */
  liftOnHover?: boolean;
  /** Whether to show a tooltip with the avatar's alt text on hover. Defaults to true. */
  showTooltip?: boolean;
  /** Alias for showTooltip. */
  tooltip?: boolean;
}

export const AvatarStack = React.forwardRef<HTMLDivElement, AvatarStackProps>(
  (
    {
      avatars,
      size = "md",
      variant = "default",
      invertOverlap = true,
      translate = "-30%",
      max = 4,
      ringClassName = "ring-background",
      action,
      spreadOnHover = false,
      liftOnHover = false,
      showTooltip = true,
      tooltip = true,
      className,
      ...props
    },
    ref,
  ) => {
    const s = SIZES[size] ?? SIZES.md;
    const shown = avatars.slice(0, max);
    const rest = avatars.length - shown.length;
    const enableTooltip = showTooltip && tooltip;

    // Shift on hover variant (matches animate-ui behavior)
    if (variant === "shift") {
      return (
        <AvatarGroup
          ref={ref}
          invertOverlap={invertOverlap}
          translate={translate}
          className={className}
          {...props}
        >
          {shown.map((a, i) => (
            <Avatar
              key={i}
              className={cn(s.box, "border-3 border-background ring-0 cursor-pointer", ringClassName)}
            >
              <img src={a.src} alt={a.alt ?? a.name ?? ""} className="h-full w-full object-cover" />
              {(enableTooltip && (a.tooltip || a.alt || a.name)) && (
                <AvatarGroupTooltip designation={a.designation || a.role}>
                  {a.name || a.tooltip || a.alt}
                </AvatarGroupTooltip>
              )}
            </Avatar>
          ))}
          {rest > 0 && (
            <Avatar
              className={cn(
                s.box,
                "border-3 border-background ring-0 bg-muted text-muted-foreground font-semibold text-xs flex items-center justify-center cursor-pointer",
                ringClassName,
              )}
            >
              +{rest}
            </Avatar>
          )}
          {action}
        </AvatarGroup>
      );
    }

    // Default variant
    // Layering comes from `--as-z` so a hover class can still win over it.
    const disc = cn(
      "relative z-[var(--as-z)] grid shrink-0 place-items-center overflow-hidden rounded-full ring-2 transition-transform duration-300 ease-out cursor-pointer",
      s.box,
      ringClassName,
      liftOnHover && "hover:z-50 hover:scale-115",
    );

    return (
      <div
        ref={ref}
        className={cn("group flex items-center", s.overlap, className)}
        {...props}
      >
        {shown.map((a, i) => {
          const avatarElement = (
            <span
              key={a.src}
              className={cn(disc, "bg-muted")}
              // Each face slides a touch further than the last, so the row fans out.
              style={{ "--as-shift": `${i * 3}px`, "--as-z": shown.length - i } as React.CSSProperties}
            >
              <img src={a.src} alt={a.alt ?? a.name ?? ""} className="h-full w-full object-cover" />
            </span>
          );

          if (enableTooltip && (a.tooltip || a.alt || a.name)) {
            return (
              <Tooltip key={a.src}>
                <TooltipTrigger asChild>{avatarElement}</TooltipTrigger>
                <TooltipContent side="top">
                  <div className="flex flex-col items-center">
                    <span className="font-semibold text-xs">{a.name || a.tooltip || a.alt}</span>
                    {(a.designation || a.role) && (
                      <span className="text-[10px] text-muted-foreground mt-0.5">{a.designation || a.role}</span>
                    )}
                  </div>
                </TooltipContent>
              </Tooltip>
            );
          }

          return avatarElement;
        })}
        {rest > 0 && (
          <span
            className={cn(disc, "bg-primary font-semibold text-primary-foreground", s.text)}
            style={{ "--as-shift": `${shown.length * 3}px`, "--as-z": 0 } as React.CSSProperties}
          >
            +{rest}
          </span>
        )}
        {action && (
          <span
            className={cn(disc, "overflow-visible ring-0")}
            style={{ "--as-shift": `${(shown.length + (rest > 0 ? 1 : 0)) * 3}px`, "--as-z": 0 } as React.CSSProperties}
          >
            {action}
          </span>
        )}
      </div>
    );
  },
);
AvatarStack.displayName = "AvatarStack";

export default AvatarStack;

"use client";

import { cn } from "@/lib/utils";
import React, {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";

/**
 * Positioning has to happen before the browser paints, or the tooltip shows up
 * at its placeholder coordinates for one frame and then jumps into place.
 * useLayoutEffect warns when it runs on the server, and TooltipContent renders
 * nothing until the trigger has committed, so falling back to useEffect there
 * costs nothing.
 */
const useIsomorphicLayoutEffect =
  typeof window !== "undefined" ? useLayoutEffect : useEffect;

// ==========================================
// 1. CONTEXT
// ==========================================
interface TooltipContextType {
  open: boolean;
  setOpen: React.Dispatch<React.SetStateAction<boolean>>;
  delayDuration: number;
  /**
   * The trigger node itself, held in state rather than a ref. A ref shared
   * through context makes every read of this context a ref read during render;
   * a plain node lets the content position and portal itself without one.
   */
  trigger: HTMLDivElement | null;
  setTrigger: React.Dispatch<React.SetStateAction<HTMLDivElement | null>>;
}
const TooltipContext = createContext<TooltipContextType | undefined>(undefined);

// ==========================================
// 2. PROVIDER (Optional: For wrapping the app)
// ==========================================
export function TooltipProvider({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

// ==========================================
// 3. TOOLTIP ROOT (State Manager)
// ==========================================
export interface TooltipProps {
  children: React.ReactNode;
  delayDuration?: number;
}

export function Tooltip({ children, delayDuration = 200 }: TooltipProps) {
  const [open, setOpen] = useState(false);
  const [trigger, setTrigger] = useState<HTMLDivElement | null>(null);

  // The open/close delay is owned by the trigger, not shared through context:
  // a timeout ref captured by a context handler would make every read of this
  // context look like a ref read during render.
  const value = useMemo(
    () => ({ open, setOpen, delayDuration, trigger, setTrigger }),
    [open, delayDuration, trigger],
  );

  return (
    <TooltipContext.Provider value={value}>
      {children}
    </TooltipContext.Provider>
  );
}

// ==========================================
// 4. TRIGGER
// ==========================================
export interface TooltipTriggerProps
  extends React.HTMLAttributes<HTMLDivElement> {
  asChild?: boolean;
}

export function TooltipTrigger({
  children,
  className,
  ...props
}: TooltipTriggerProps) {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("TooltipTrigger must be used within a Tooltip");

  const { open, setOpen, delayDuration, setTrigger } = context;
  const timeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const handleOpen = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    timeoutRef.current = setTimeout(() => setOpen(true), delayDuration);
  }, [setOpen, delayDuration]);

  const handleClose = useCallback(() => {
    if (timeoutRef.current) clearTimeout(timeoutRef.current);
    setOpen(false);
  }, [setOpen]);

  useEffect(
    () => () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    },
    [],
  );

  return (
    <div
      ref={setTrigger}
      onMouseEnter={handleOpen}
      onMouseLeave={handleClose}
      onFocus={handleOpen}
      onBlur={handleClose}
      className={cn("inline-block", className)}
      tabIndex={0}
      aria-haspopup="dialog"
      aria-expanded={open}
      {...props}
    >
      {children}
    </div>
  );
}

// ==========================================
// 5. CONTENT (Portal Renderer)
// ==========================================
export interface TooltipContentProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, "title"> {
  side?: "top" | "right" | "bottom" | "left";
  align?: "start" | "center" | "end";
  sideOffset?: number;
  /** Whether to render a pointer arrow anchoring to the trigger. Defaults to false. */
  showArrow?: boolean;
  /** Custom classes for the pointer arrow element. */
  arrowClassName?: string;
  /** Whether to enable a smooth pull-out animation sliding gently out from the trigger. Can also be set to "staggered" for sequential icon, title, and description entrance, or "expand" for dynamic height/width expansion. */
  animated?: boolean | "pull-out" | "staggered" | "expand";
  /** Whether to animate child elements (icon -> title -> description) in a staggered cascade. Defaults to false. */
  staggered?: boolean;
  /** Whether to start with only title space and smoothly expand height (for top/bottom) or width (for left/right) to unveil the description. Defaults to false. */
  expand?: boolean;
  /** Optional title header displayed in bold. */
  title?: React.ReactNode;
  /** Optional description text. */
  description?: React.ReactNode;
  /** Shorthand alias for description. */
  des?: React.ReactNode;
  /** Optional leading icon displayed next to the content. */
  icon?: React.ReactNode;
  /** Optional custom classes for the icon background container. */
  iconClassName?: string;
}

interface TooltipContentContextType {
  side: NonNullable<TooltipContentProps["side"]>;
  align: NonNullable<TooltipContentProps["align"]>;
}

const TooltipContentContext = createContext<TooltipContentContextType | null>(null);

const ARROW_POSITIONS: Record<
  NonNullable<TooltipContentProps["side"]>,
  Record<NonNullable<TooltipContentProps["align"]>, string>
> = {
  top: {
    center: "-bottom-1 left-1/2 -translate-x-1/2",
    start: "-bottom-1 left-3",
    end: "-bottom-1 right-3",
  },
  bottom: {
    center: "-top-1 left-1/2 -translate-x-1/2",
    start: "-top-1 left-3",
    end: "-top-1 right-3",
  },
  left: {
    center: "-right-1 top-1/2 -translate-y-1/2",
    start: "-right-1 top-3",
    end: "-right-1 bottom-3",
  },
  right: {
    center: "-left-1 top-1/2 -translate-y-1/2",
    start: "-left-1 top-3",
    end: "-left-1 bottom-3",
  },
};

const ARROW_BORDERS: Record<NonNullable<TooltipContentProps["side"]>, string> = {
  top: "border-b border-r",
  bottom: "border-t border-l",
  left: "border-t border-r",
  right: "border-b border-l",
};

export interface TooltipArrowProps
  extends React.HTMLAttributes<HTMLSpanElement> {
  className?: string;
}

export function TooltipArrow({ className, ...props }: TooltipArrowProps) {
  const context = useContext(TooltipContentContext);
  const side = context?.side ?? "top";
  const align = context?.align ?? "center";

  return (
    <span
      aria-hidden="true"
      className={cn(
        "absolute w-2 h-2 rotate-45 bg-inherit border-inherit pointer-events-none",
        ARROW_POSITIONS[side][align],
        ARROW_BORDERS[side],
        className,
      )}
      {...props}
    />
  );
}

// Precise transform origin mapped to the pointer arrow anchor position.
const ARROW_ORIGINS: Record<
  NonNullable<TooltipContentProps["side"]>,
  Record<NonNullable<TooltipContentProps["align"]>, string>
> = {
  top: {
    center: "origin-bottom",
    start: "origin-bottom-left",
    end: "origin-bottom-right",
  },
  bottom: {
    center: "origin-top",
    start: "origin-top-left",
    end: "origin-top-right",
  },
  left: {
    center: "origin-right",
    start: "origin-top-right",
    end: "origin-bottom-right",
  },
  right: {
    center: "origin-left",
    start: "origin-top-left",
    end: "origin-bottom-left",
  },
};

// The entrance grows out of the trigger's edge: a tooltip above the trigger
// scales from its own bottom edge and slides up a touch, and so on.
const ENTER_FROM_SIDE: Record<NonNullable<TooltipContentProps["side"]>, string> = {
  top: "origin-bottom slide-in-from-bottom-1",
  bottom: "origin-top slide-in-from-top-1",
  left: "origin-right slide-in-from-right-1",
  right: "origin-left slide-in-from-left-1",
};

// Slower, smoother emergence for the staggered cascade variant.
const ENTER_STAGGERED: Record<NonNullable<TooltipContentProps["side"]>, string> = {
  top: "origin-bottom slide-in-from-bottom-3 zoom-in-90 duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]",
  bottom: "origin-top slide-in-from-top-3 zoom-in-90 duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]",
  left: "origin-right slide-in-from-right-3 zoom-in-90 duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]",
  right: "origin-left slide-in-from-left-3 zoom-in-90 duration-500 ease-[cubic-bezier(0.16,1,0.3,1)]",
};

export function TooltipContent({
  side = "top",
  align = "center",
  sideOffset = 6,
  showArrow = false,
  arrowClassName,
  animated = false,
  staggered = false,
  expand = false,
  title,
  description,
  des,
  icon,
  iconClassName,
  className,
  children,
  ...props
}: TooltipContentProps) {
  const context = useContext(TooltipContext);
  if (!context) throw new Error("TooltipContent must be used within a Tooltip");

  const effectiveOffset = sideOffset === 6 && showArrow ? 8 : sideOffset;
  const { open, trigger: triggerEl } = context;
  const [coords, setCoords] = useState({ top: -9999, left: -9999 });
  // Stale coordinates from the previous open would otherwise paint first.
  const [positioned, setPositioned] = useState(false);
  const [expanded, setExpanded] = useState(false);
  const contentRef = useRef<HTMLDivElement>(null);

  const resolvedDes = description ?? des;
  const isExpand = Boolean(expand || animated === "expand");
  const isStaggered = Boolean(!isExpand && (staggered || animated === "staggered"));
  const isArrowEmerge = Boolean(!isExpand && !isStaggered && (animated === true || animated === "pull-out"));

  // Forget the measurement on close, so the next open cannot flash at last
  // time’s coordinates before the layout effect re-measures.
  const [wasOpen, setWasOpen] = useState(open);
  if (wasOpen !== open) {
    setWasOpen(open);
    if (!open) {
      setPositioned(false);
      setExpanded(false);
    }
  }

  // Expand variant: first emerges out of the arrow (animated=true style), then smoothly expands width & height
  useEffect(() => {
    if (!open || !isExpand) {
      setExpanded(false);
      return;
    }
    const timer = setTimeout(() => {
      setExpanded(true);
    }, 350);
    return () => clearTimeout(timer);
  }, [open, isExpand]);

  useIsomorphicLayoutEffect(() => {
    if (!open || !triggerEl || !contentRef.current) return;

    // Resolve the document/window the trigger actually lives in, so the
    // tooltip works when rendered inside an iframe (e.g. docs device preview).
    const doc = triggerEl.ownerDocument;
    const win = doc.defaultView ?? window;

    const updatePosition = () => {
      const trigger = triggerEl.getBoundingClientRect();
      // offsetWidth/Height are the untransformed layout box; a bounding rect
      // would report the shrunken size while the zoom-in entrance runs.
      const content = {
        width: contentRef.current!.offsetWidth,
        height: contentRef.current!.offsetHeight,
      };
      let top = 0;
      let left = 0;

      // 1. Calculate Side
      if (side === "top") top = trigger.top - content.height - effectiveOffset;
      if (side === "bottom") top = trigger.bottom + effectiveOffset;
      if (side === "left") left = trigger.left - content.width - effectiveOffset;
      if (side === "right") left = trigger.right + effectiveOffset;

      // 2. Calculate Align
      if (side === "top" || side === "bottom") {
        if (align === "center")
          left = trigger.left + trigger.width / 2 - content.width / 2;
        if (align === "start") left = trigger.left;
        if (align === "end") left = trigger.right - content.width;
      } else {
        if (align === "center")
          top = trigger.top + trigger.height / 2 - content.height / 2;
        if (align === "start") top = trigger.top;
        if (align === "end") top = trigger.bottom - content.height;
      }

      // Clamp within viewport padding to prevent overflowing screen edges
      const viewportPadding = 8;
      const docWidth = doc.documentElement.clientWidth || win.innerWidth;
      const extraLeftShift =
        isExpand && side === "left"
          ? 146
          : isExpand && (side === "top" || side === "bottom")
            ? 73
            : 0;
      const minLeft = viewportPadding + extraLeftShift;
      const maxLeft = Math.max(
        minLeft,
        docWidth - content.width - (isExpand && (side === "top" || side === "bottom") ? 73 : 0) - viewportPadding,
      );
      left = Math.max(minLeft, Math.min(left, maxLeft));

      setCoords({ top: top + win.scrollY, left: left + win.scrollX });
      setPositioned(true);
    };

    updatePosition();
    // Use capture phase for scroll to ensure it updates during nested scroll containers
    win.addEventListener("scroll", updatePosition, true);
    win.addEventListener("resize", updatePosition);
    return () => {
      win.removeEventListener("scroll", updatePosition, true);
      win.removeEventListener("resize", updatePosition);
    };
  }, [open, side, align, effectiveOffset, triggerEl, isExpand]);

  // triggerEl is null until the trigger commits, which also covers SSR: there
  // is no document to portal into on the server.
  if (!triggerEl || !open) return null;

  // Portal into the trigger's own document (supports iframe rendering).
  const portalTarget = triggerEl.ownerDocument.body;

  const hasStructured = Boolean(title || resolvedDes || icon);

  // Slim, snug dimensions for the expand variant:
  // Starts as a compact badge (150px wide, 42px high) showing icon and title.
  // Expands in width to 296px (+146px) across ALL directions (top, bottom, left, right),
  // with a gentle, slim height increase (42px -> 56px, only +14px) to fit the description underneath.
  const expandWidth = expanded ? "296px" : "150px";
  const expandHeight = expanded ? "56px" : "42px";

  let expandTransform = "none";
  if (isExpand) {
    const alignCenter = align === "center";
    if (side === "top") {
      // Offset width expansion symmetrically by 73px to keep centered on trigger
      // Offset 14px height expansion to keep bottom edge and arrow pinned
      const tx = alignCenter ? (expanded ? "-73px" : "0px") : "0px";
      const ty = expanded ? "-14px" : "0px";
      expandTransform = `translateX(${tx}) translateY(${ty})`;
    } else if (side === "bottom") {
      // Offset width expansion symmetrically by 73px to keep centered on trigger
      // Natural downward height expansion keeps top edge and arrow pinned
      const tx = alignCenter ? (expanded ? "-73px" : "0px") : "0px";
      expandTransform = `translateX(${tx}) translateY(0px)`;
    } else if (side === "left") {
      // Offset full 146px width expansion to keep right edge and arrow pinned
      // Offset 7px vertical shift to keep arrow centered
      const tx = expanded ? "-146px" : "0px";
      const ty = alignCenter ? (expanded ? "-7px" : "0px") : "0px";
      expandTransform = `translateX(${tx}) translateY(${ty})`;
    } else if (side === "right") {
      // Natural rightward width expansion keeps left edge pinned
      // Offset 7px vertical shift to keep arrow centered
      const ty = alignCenter ? (expanded ? "-7px" : "0px") : "0px";
      expandTransform = `translateX(0px) translateY(${ty})`;
    }
  }

  if (isExpand) {
    return createPortal(
      <TooltipContentContext.Provider value={{ side, align }}>
        <div
          style={{
            position: "absolute",
            top: coords.top,
            left: coords.left,
            visibility: positioned ? "visible" : "hidden",
            zIndex: 9999,
            pointerEvents: "none",
            transformOrigin: ARROW_ORIGINS[side]?.[align] ?? "center",
            animation: positioned
              ? `tooltip-emerge-${side} 480ms cubic-bezier(0.16, 1, 0.3, 1) both`
              : undefined,
            willChange: "transform, opacity",
          }}
        >
          <div
            ref={contentRef}
            role="tooltip"
            className={cn(
              "relative text-xs text-primary-foreground bg-primary shadow-md pointer-events-none box-border px-3.5 rounded-lg flex items-center overflow-visible",
              className,
            )}
            style={{
              width: expandWidth,
              height: expandHeight,
              transform: expandTransform,
              transition:
                "width 1200ms cubic-bezier(0.16, 1, 0.3, 1), height 1200ms cubic-bezier(0.16, 1, 0.3, 1), transform 1200ms cubic-bezier(0.16, 1, 0.3, 1)",
              willChange: "width, height, transform",
            }}
            {...props}
          >
            <style>{`
              @keyframes tooltip-emerge-top {
                0% {
                  opacity: 0;
                  transform: translateY(12px) scale(0.08);
                }
                25% {
                  opacity: 1;
                }
                100% {
                  opacity: 1;
                  transform: translateY(0) scale(1);
                }
              }
              @keyframes tooltip-emerge-bottom {
                0% {
                  opacity: 0;
                  transform: translateY(-12px) scale(0.08);
                }
                25% {
                  opacity: 1;
                }
                100% {
                  opacity: 1;
                  transform: translateY(0) scale(1);
                }
              }
              @keyframes tooltip-emerge-left {
                0% {
                  opacity: 0;
                  transform: translateX(12px) scale(0.08);
                }
                25% {
                  opacity: 1;
                }
                100% {
                  opacity: 1;
                  transform: translateX(0) scale(1);
                }
              }
              @keyframes tooltip-emerge-right {
                0% {
                  opacity: 0;
                  transform: translateX(-12px) scale(0.08);
                }
                25% {
                  opacity: 1;
                }
                100% {
                  opacity: 1;
                  transform: translateX(0) scale(1);
                }
              }
              @media (prefers-reduced-motion: reduce) {
                * {
                  animation: none !important;
                }
              }
            `}</style>
            <div className="flex items-center gap-2.5 w-full h-full min-w-0">
              {icon && (
                <div
                  className={cn(
                    "size-7 rounded-lg bg-primary-foreground/15 flex items-center justify-center shrink-0 text-current [&_svg]:size-3.5 shadow-2xs",
                    iconClassName,
                  )}
                >
                  {icon}
                </div>
              )}
              <div className="flex flex-col flex-1 min-w-0 justify-center">
                {title && (
                  <div className="font-semibold text-xs leading-none tracking-tight text-primary-foreground truncate whitespace-nowrap">
                    {title}
                  </div>
                )}
                {resolvedDes && (
                  <div
                    className="overflow-hidden min-h-0"
                    style={{
                      maxHeight: expanded ? "18px" : "0px",
                      opacity: expanded ? 0.85 : 0,
                      transform: expanded ? "translateY(0)" : "translateY(-3px)",
                      transition:
                        "max-height 1200ms cubic-bezier(0.16, 1, 0.3, 1), opacity 800ms cubic-bezier(0.16, 1, 0.3, 1) 220ms, transform 1200ms cubic-bezier(0.16, 1, 0.3, 1)",
                      willChange: "max-height, opacity, transform",
                    }}
                  >
                    <div className="text-[11px] leading-tight text-primary-foreground/85 pt-1 truncate whitespace-nowrap">
                      {resolvedDes}
                    </div>
                  </div>
                )}
                {children}
              </div>
            </div>
            {showArrow && <TooltipArrow className={arrowClassName} />}
          </div>
        </div>
      </TooltipContentContext.Provider>,
      portalTarget,
    );
  }

  // Classic and Staggered variants
  const entranceClass = isArrowEmerge
    ? ""
    : isStaggered
      ? ENTER_STAGGERED[side]
      : cn("zoom-in-95 duration-150", ENTER_FROM_SIDE[side]);

  return createPortal(
    <TooltipContentContext.Provider value={{ side, align }}>
      <div
        ref={contentRef}
        role="tooltip"
        className={cn(
          "absolute z-[9999] text-xs text-primary-foreground bg-primary shadow-md pointer-events-none box-border",
          isArrowEmerge && (ARROW_ORIGINS[side]?.[align] ?? "origin-center"),
          title
            ? "px-3.5 py-2.5 rounded-lg max-w-xs"
            : "px-3 py-1.5 rounded-md font-medium",
          !isArrowEmerge && "transition-none",
          entranceClass,
          className,
        )}
        style={
          {
            top: coords.top,
            left: coords.left,
            visibility: positioned ? "visible" : "hidden",
            ...(isArrowEmerge
              ? {
                  animation: positioned
                    ? `tooltip-emerge-${side} 600ms cubic-bezier(0.16, 1, 0.3, 1) both`
                    : undefined,
                  willChange: "transform, opacity",
                }
              : undefined),
          } as React.CSSProperties
        }
        {...props}
      >
        {isArrowEmerge && (
          <style>{`
            @keyframes tooltip-emerge-top {
              0% {
                opacity: 0;
                transform: translateY(12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-emerge-bottom {
              0% {
                opacity: 0;
                transform: translateY(-12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateY(0) scale(1);
              }
            }
            @keyframes tooltip-emerge-left {
              0% {
                opacity: 0;
                transform: translateX(12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateX(0) scale(1);
              }
            }
            @keyframes tooltip-emerge-right {
              0% {
                opacity: 0;
                transform: translateX(-12px) scale(0.08);
              }
              25% {
                opacity: 1;
              }
              100% {
                opacity: 1;
                transform: translateX(0) scale(1);
              }
            }
            @media (prefers-reduced-motion: reduce) {
              * {
                animation: none !important;
              }
            }
          `}</style>
        )}
        {isStaggered && (
          <style>{`
            @keyframes tooltip-icon-pop {
              0% {
                opacity: 0;
                transform: scale(0.3) translateY(4px);
              }
              65% {
                opacity: 1;
                transform: scale(1.08) translateY(-1px);
              }
              100% {
                opacity: 1;
                transform: scale(1) translateY(0);
              }
            }
            @keyframes tooltip-title-in {
              0% {
                opacity: 0;
                transform: translateY(6px);
              }
              100% {
                opacity: 1;
                transform: translateY(0);
              }
            }
            @keyframes tooltip-des-in {
              0% {
                opacity: 0;
                transform: translateY(6px);
              }
              100% {
                opacity: 1;
                transform: translateY(0);
              }
            }
            @media (prefers-reduced-motion: reduce) {
              .tooltip-anim-icon,
              .tooltip-anim-title,
              .tooltip-anim-des {
                animation: none !important;
                opacity: 1 !important;
                transform: none !important;
              }
            }
          `}</style>
        )}
        {hasStructured ? (
          isExpand ? (
            <div className="flex items-center gap-2.5 w-full h-full min-w-0">
              {icon && (
                <div
                  className={cn(
                    "size-7 rounded-lg bg-primary-foreground/15 flex items-center justify-center shrink-0 text-current [&_svg]:size-3.5 shadow-2xs",
                    iconClassName,
                  )}
                >
                  {icon}
                </div>
              )}
              <div className="flex flex-col flex-1 min-w-0 justify-center">
                {title && (
                  <div className="font-semibold text-xs leading-none tracking-tight text-primary-foreground truncate whitespace-nowrap">
                    {title}
                  </div>
                )}
                {resolvedDes && (
                  <div
                    className="overflow-hidden min-h-0"
                    style={{
                      maxHeight: expanded ? "18px" : "0px",
                      opacity: expanded ? 0.85 : 0,
                      transform: expanded ? "translateY(0)" : "translateY(-3px)",
                      transition:
                        "max-height 1200ms cubic-bezier(0.16, 1, 0.3, 1), opacity 800ms cubic-bezier(0.16, 1, 0.3, 1) 220ms, transform 1200ms cubic-bezier(0.16, 1, 0.3, 1)",
                      willChange: "max-height, opacity, transform",
                    }}
                  >
                    <div className="text-[11px] leading-tight text-primary-foreground/85 pt-1 truncate whitespace-nowrap">
                      {resolvedDes}
                    </div>
                  </div>
                )}
                {children}
              </div>
            </div>
          ) : (
            <div className="flex items-center gap-2.5 max-w-xs">
              {icon && (
                <div
                  className={cn(
                    "size-8 rounded-lg bg-primary-foreground/15 flex items-center justify-center shrink-0 text-current [&_svg]:size-4 shadow-2xs",
                    isStaggered && "tooltip-anim-icon",
                    iconClassName,
                  )}
                  style={
                    isStaggered
                      ? {
                          animation: "tooltip-icon-pop 380ms cubic-bezier(0.16, 1, 0.3, 1) 80ms both",
                          willChange: "transform, opacity",
                        }
                      : undefined
                  }
                >
                  {icon}
                </div>
              )}
              <div className="flex flex-col min-w-0 justify-center">
                {title && (
                  <div
                    className={cn(
                      "font-semibold text-xs leading-tight tracking-tight text-primary-foreground truncate whitespace-nowrap",
                      isStaggered && "tooltip-anim-title",
                    )}
                    style={
                      isStaggered
                        ? {
                            animation: "tooltip-title-in 360ms cubic-bezier(0.16, 1, 0.3, 1) 200ms both",
                            willChange: "transform, opacity",
                          }
                        : undefined
                    }
                  >
                    {title}
                  </div>
                )}
                {resolvedDes && (
                  <div
                    className={cn(
                      "text-xs leading-tight truncate whitespace-nowrap",
                      title
                        ? "opacity-85 text-[11px] mt-0.5"
                        : "font-medium opacity-95",
                      isStaggered && "tooltip-anim-des",
                    )}
                    style={
                      isStaggered
                        ? {
                            animation: `tooltip-des-in 380ms cubic-bezier(0.16, 1, 0.3, 1) ${title ? 320 : 200}ms both`,
                            willChange: "transform, opacity",
                          }
                        : undefined
                    }
                  >
                    {resolvedDes}
                  </div>
                )}
                {children}
              </div>
            </div>
          )
        ) : (
          children
        )}
        {showArrow && <TooltipArrow className={arrowClassName} />}
      </div>
    </TooltipContentContext.Provider>,
    portalTarget,
  );
}

"use client";

import * as AvatarPrimitive from "@radix-ui/react-avatar";
import * as React from "react";

import { cn } from "@/lib/utils";

type AvatarRootProps = React.ComponentPropsWithoutRef<
  typeof AvatarPrimitive.Root
>;
type AvatarImageProps = React.ComponentPropsWithoutRef<
  typeof AvatarPrimitive.Image
>;
type AvatarFallbackProps = React.ComponentPropsWithoutRef<
  typeof AvatarPrimitive.Fallback
>;

function Avatar({ className, ...props }: AvatarRootProps) {
  return (
    <AvatarPrimitive.Root
      data-slot="avatar"
      className={cn(
        // Fixed: Replaced `size-8` with explicit `h-8 w-8`
        "relative flex h-8 w-8 shrink-0 overflow-hidden rounded-full items-center justify-center",
        className,
      )}
      {...props}
    />
  );
}

function AvatarImage({ className, ...props }: AvatarImageProps) {
  return (
    <AvatarPrimitive.Image
      data-slot="avatar-image"
      // Fixed: Replaced `size-full` with `h-full w-full` and added `object-cover`
      className={cn("aspect-square h-full w-full object-cover", className)}
      {...props}
    />
  );
}

function AvatarFallback({ className, ...props }: AvatarFallbackProps) {
  return (
    <AvatarPrimitive.Fallback
      data-slot="avatar-fallback"
      className={cn(
        // Fixed: Replaced `size-full` with `h-full w-full`
        "bg-muted flex h-full w-full items-center justify-center rounded-full",
        className,
      )}
      {...props}
    />
  );
}

export { Avatar, AvatarFallback, AvatarImage };
